- ansible.builtin.stat: {path: /etc/foo.conf}
  register: st
- ansible.builtin.fail: {msg: "ownership changed"}
  when: st.stat.pw_name != 'root'

- ansible.builtin.stat: {path: /path/to/something}
  register: p
- ansible.builtin.debug: {msg: "is a directory"}
  when: p.stat.isdir is defined and p.stat.isdir
